using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.VTS.TipoIdentificacion;using GraphApi.Services.VTS.TipoIdentificacion;namespace GraphApi.Controllers.VTS.TipoIdentificacion{    /// <summary>    /// Gestión de TipoIdentificacions: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("VTS/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre TipoIdentificacions")]    public class TipoIdentificacionController : Controller    {        private readonly ITipoIdentificacionService _objService;        public TipoIdentificacionController(ITipoIdentificacionService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los TipoIdentificacions, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="tipoIdentificacionID">TipoIdentificacionID</param>        /// <param name="tipoIdentificacion">TipoIdentificacion</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de TipoIdentificacions</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar TipoIdentificacions",            Description = "Devuelve TipoIdentificacions aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadTipoIdentificacion>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadTipoIdentificacion>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? tipoIdentificacionID,            [FromQuery] string? tipoIdentificacion,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetTipoIdentificacionsDynamic(                tipoIdentificacionID,                 tipoIdentificacion,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo TipoIdentificacion.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del TipoIdentificacion a crear.</param>        /// <returns>El TipoIdentificacion recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear TipoIdentificacions",            Description = "Inserta un nuevo TipoIdentificacion en la base de datos."        )]        [ProducesResponseType(typeof(clReadTipoIdentificacion), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadTipoIdentificacion>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateTipoIdentificacion objInput)        {            var vCreated = await _objService.CreateTipoIdentificacion(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de TipoIdentificacion.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del TipoIdentificacion.</param>        /// <returns>El TipoIdentificacion actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar TipoIdentificacions",            Description = "Actualiza uno o varios campos de TipoIdentificacion existente."        )]        [ProducesResponseType(typeof(clReadTipoIdentificacion), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadTipoIdentificacion>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateTipoIdentificacion objInput)        {            var vUpdated = await _objService.UpdateTipoIdentificacion(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un TipoIdentificacion por su ID.        /// </summary>        [HttpDelete("{nTipoIdentificacionID:int}")]        [SwaggerOperation(            Summary = "Eliminar TipoIdentificacion",            Description = "Borra un TipoIdentificacion si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nTipoIdentificacionID)        {            var success = await _objService.DeleteTipoIdentificacion(nTipoIdentificacionID);            return success ? NoContent() : NotFound();        }    }}